/* Prototype preview bar. NOT theme JS: it only switches scheme, preset and language
   so a reviewer can check every combination. Pages work without it.
   Markup contract (generated by tools/build_prototypes.py):
     <html data-scheme="light" data-theme-slug="table" data-presets="classic,app,…" data-preset="classic">
     <link id="proto-preset" rel="stylesheet" href="../../../kit/table/css/preset-classic.css">
     <script src="../../_kit/proto.js" defer></script>
*/
(function () {
  'use strict';
  var root = document.documentElement;
  var KEY = 'proto:' + (root.getAttribute('data-theme-slug') || 'x');

  function load() { try { return JSON.parse(localStorage.getItem(KEY) || '{}'); } catch (e) { return {}; } }
  function save(s) { try { localStorage.setItem(KEY, JSON.stringify(s)); } catch (e) { /* storage blocked: ignore */ } }

  var state = load();
  // ?scheme=dark&preset=app override the saved choice for this load only (used by tools/shoot.py).
  var q = {};
  location.search.replace(/[?&]([a-z]+)=([a-z0-9-]+)/g, function (m, k, v) { q[k] = v; });
  if (q.scheme) state.scheme = q.scheme;
  if (q.preset) state.preset = q.preset;
  var presets = (root.getAttribute('data-presets') || '').split(',').filter(Boolean);
  var link = document.getElementById('proto-preset');

  function apply() {
    if (state.scheme) root.setAttribute('data-scheme', state.scheme);
    if (state.preset && link && presets.indexOf(state.preset) !== -1) {
      link.href = link.href.replace(/preset-[a-z0-9-]+\.css$/, 'preset-' + state.preset + '.css');
      root.setAttribute('data-preset', state.preset);
    }
  }

  function el(tag, attrs, text) {
    var n = document.createElement(tag);
    Object.keys(attrs || {}).forEach(function (k) { n.setAttribute(k, attrs[k]); });
    if (text) n.textContent = text;
    return n;
  }

  function select(id, label, options, current, onChange) {
    var wrap = el('label', { 'for': id, 'class': 'proto-bar__field' }, label + ' ');
    var s = el('select', { id: id });
    options.forEach(function (o) {
      var opt = el('option', { value: o }, o);
      if (o === current) opt.selected = true;
      s.appendChild(opt);
    });
    s.addEventListener('change', function () { onChange(s.value); });
    wrap.appendChild(s);
    return wrap;
  }

  function bar() {
    var b = el('div', { 'class': 'proto-bar', role: 'region', 'aria-label': 'Prototype controls' });
    b.appendChild(select('proto-scheme', 'Scheme', ['light', 'dark', 'auto'], root.getAttribute('data-scheme'), function (v) {
      state.scheme = v; save(state); apply();
    }));
    if (presets.length) {
      b.appendChild(select('proto-preset-select', 'Preset', presets, root.getAttribute('data-preset'), function (v) {
        state.preset = v; save(state); apply();
      }));
    }
    var other = root.lang === 'ar' ? 'en' : 'ar';
    var href = location.pathname.replace(/\/(en|ar)\/([^/]*)$/, '/' + other + '/$2');
    b.appendChild(el('a', { href: href, 'class': 'proto-bar__link', hreflang: other }, other === 'ar' ? 'العربية' : 'English'));
    b.appendChild(el('a', { href: '../../index.html', 'class': 'proto-bar__link' }, 'All screens'));
    document.body.appendChild(b);
  }

  apply();
  // ?shoot=1: report the page height so tools/shoot.py can size a full-page screenshot.
  if (q.shoot) window.addEventListener('load', function () {
    root.setAttribute('data-shoot-h', String(document.documentElement.scrollHeight));
  });
  if (!/[?&]bar=0\b/.test(location.search)) {
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bar); else bar();
  }
})();
